CREATE TABLE pilot_value_inputs(location_id uuid PRIMARY KEY REFERENCES provider_locations(id),baseline_cases integer CHECK(baseline_cases>=0),pilot_cases integer CHECK(pilot_cases>=0),baseline_admin_minutes integer CHECK(baseline_admin_minutes>=0),pilot_admin_minutes integer CHECK(pilot_admin_minutes>=0),hourly_cost_cents integer CHECK(hourly_cost_cents>=0),incremental_visits integer CHECK(incremental_visits>=0),contribution_per_visit_cents integer CHECK(contribution_per_visit_cents>=0),subscription_cents integer CHECK(subscription_cents>=0),other_cost_cents integer CHECK(other_cost_cents>=0),onboarding_hours numeric(8,2) CHECK(onboarding_hours>=0),support_hours numeric(8,2) CHECK(support_hours>=0),measurement_method text,version integer NOT NULL DEFAULT 1,updated_by text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
